"""Build a portable offline study document from the reviewed manuscript."""
from pathlib import Path
import hashlib
import html
import json
import re
import markdown

ROOT=Path(__file__).resolve().parents[1]
source=ROOT/'docs/NEXUS_Interview_Handbook.md'
raw=source.read_text(encoding='utf-8')
converted=markdown.markdown(raw.replace('<details class="qa">','<details class="qa" markdown="1">'),extensions=['tables','fenced_code','toc','md_in_html'])
converted=re.sub(r'^<h1[^>]*>.*?</h1>\s*','',converted,count=1,flags=re.S)
pieces=re.split(r'(?=<h2 id=")',converted)
sections=[]
navigation=[]
for part in pieces:
    if not part.strip():
        continue
    match=re.match(r'<h2 id="([^"]+)">(.*?)</h2>',part,re.S)
    if not match:
        raise ValueError('Unexpected content before chapter')
    identifier,title=match.groups()
    part=re.sub(r'(<table>.*?</table>)',r'<div class="table-scroll">\1</div>',part,flags=re.S)
    sections.append(f'<section class="chapter" id="section-{identifier}" aria-labelledby="{identifier}">{part}<label class="complete"><input type="checkbox" data-chapter="{identifier}"> I can explain this chapter without notes</label></section>')
    navigation.append(f'<a href="#{identifier}" data-chapter-link="{identifier}">{title}</a>')

css=r'''
:root{--ink:#172b3b;--muted:#576b79;--teal:#087c75;--line:#dbe4e8;--paper:#fff;--nav:#102b3c;--bg:#eef3f5}
*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:88px}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.75 "Segoe UI",Arial,sans-serif}a{color:#08756e}button,input{font:inherit}button{cursor:pointer;border:1px solid #bfd0d8;border-radius:7px;background:white;color:var(--ink);padding:8px 12px;font-size:13px;font-weight:600}button:hover{background:#e8f4f1}button:focus-visible,a:focus-visible,input:focus-visible,summary:focus-visible{outline:3px solid #f0b95e;outline-offset:3px}nav{position:fixed;left:0;top:0;bottom:0;width:285px;background:var(--nav);color:white;padding:26px 20px;overflow-y:auto;z-index:15}nav .brand{font-size:23px;font-weight:750;letter-spacing:3px}nav .caption{font-size:12px;color:#a8c6d2;line-height:1.6;margin:4px 0 22px}nav label{font-size:12px;color:#cee0e8;display:block}nav input{width:100%;padding:10px 11px;background:#fff;border:0;border-radius:6px;margin:6px 0 8px;font-size:14px}#search-count{font-size:11px;color:#bdd5df;min-height:24px}nav a{display:block;color:#d9e7ee;text-decoration:none;border-radius:6px;margin:3px 0;padding:7px 9px;font-size:12px;line-height:1.5;border-left:3px solid transparent}nav a:hover,nav a.active{background:#22475a;border-left-color:#72d5c5;color:#fff}nav a.done:after{content:" ✓";color:#91dfc6}nav .progress{margin-top:16px;padding-top:16px;border-top:1px solid #36505f;font-size:12px;color:#d5e8ef}progress{width:100%;height:7px;accent-color:#59c6b0}.topbar{position:sticky;top:0;z-index:10;background:#ffffffed;backdrop-filter:blur(10px);border-bottom:1px solid var(--line);display:flex;gap:8px;align-items:center;justify-content:flex-end;padding:12px 28px;margin-left:285px}.topbar .label{margin-right:auto;color:var(--muted);font-size:12px}main{margin-left:285px;padding:34px 32px 65px;max-width:1440px}.cover,.chapter{max-width:1000px;margin:0 auto 26px;background:var(--paper);border:1px solid var(--line);border-radius:12px;padding:42px 48px;box-shadow:0 3px 10px #16324a04}.cover{padding-top:48px;background:linear-gradient(135deg,#fff 55%,#e9f5f0)}.eyebrow{font-size:11px;letter-spacing:2px;font-weight:700;text-transform:uppercase;color:var(--teal)}h1{font-size:44px;line-height:1.15;letter-spacing:-1.3px;margin:18px 0 20px;color:#102b3c;max-width:750px}.intro{font-size:19px;line-height:1.65;max-width:740px;color:#415969}.meta{font-size:12px;color:var(--muted);margin-top:20px}.chips{display:flex;gap:10px;flex-wrap:wrap;margin:28px 0}.chips span{background:#e8f4ee;padding:9px 13px;border-radius:6px;color:#155b50;font-size:13px;font-weight:650}.cover-note{border-left:3px solid var(--teal);padding:8px 0 8px 17px;font-size:14px;line-height:1.7}h2{font-size:27px;line-height:1.35;margin:0 0 25px;letter-spacing:-.4px;color:#173b4b}h3{font-size:19px;line-height:1.45;margin:28px 0 12px;color:#173b4b}p{margin:0 0 17px}ul,ol{margin:12px 0 22px;padding-left:25px}li{padding:3px 0}strong{font-weight:650;color:#172b3b}.table-scroll{overflow-x:auto;margin:21px 0 25px}table{border-collapse:collapse;width:100%;font-size:13px;line-height:1.6}th{background:#173b4b;color:white;text-align:left;font-weight:600}th,td{border:1px solid #cfdae0;padding:11px 13px;vertical-align:top}tr:nth-child(even) td{background:#f2f7f8}code{background:#edf2f4;border-radius:4px;padding:2px 5px;font:13px/1.6 Consolas,"Courier New",monospace;overflow-wrap:anywhere}pre{background:#102b3c;color:#e7f1f5;border-radius:8px;padding:20px;overflow-x:auto;line-height:1.65;font-size:12px;margin:20px 0 24px}pre code{background:none;color:inherit;padding:0;border:0;white-space:pre;overflow-wrap:normal;font-size:12px}details.qa{border:1px solid #cddde2;border-radius:8px;margin:12px 0;background:#fff}summary{padding:15px 17px;font-weight:650;cursor:pointer;line-height:1.55;color:#174a52;font-size:15px}details[open] summary{background:#eef7f4;border-bottom:1px solid #d5e5df;border-radius:8px 8px 0 0}details.qa p,details.qa ul{margin:17px 19px 19px;font-size:15px}details.qa summary::marker{color:var(--teal)}.complete{display:flex;align-items:center;gap:10px;border-top:1px solid var(--line);padding-top:18px;margin-top:32px;font-size:12px;color:var(--muted)}.complete input{accent-color:var(--teal);width:16px;height:16px;flex:none}.footer{max-width:1000px;margin:auto;text-align:center;color:var(--muted);font-size:12px}.mobile-menu{display:none}.mobile-close{display:none}body.study .chapter p,body.study .chapter li{font-size:17px}body.study .chapter{line-height:1.9}.chapter:target{outline:2px solid #8fc9bc}[hidden]{display:none!important}
@media(max-width:1100px){nav{width:250px;padding:22px 15px}main,.topbar{margin-left:250px}main{padding:25px 20px}.chapter,.cover{padding:30px}h1{font-size:36px}.topbar{padding:10px 20px}}
@media(max-width:760px){nav{display:none;width:285px;box-shadow:0 0 0 100vmax #0007}body.menu-open nav{display:block}main,.topbar{margin-left:0}.mobile-menu,.mobile-close{display:inline-block}.mobile-close{float:right}.topbar{gap:6px;flex-wrap:wrap;padding:9px 12px}.topbar .label{display:none}button{font-size:11px;padding:7px 9px}main{padding:18px 12px 35px}.chapter,.cover{padding:24px 19px;border-radius:8px;margin-bottom:18px}h1{font-size:32px}h2{font-size:23px}.intro{font-size:17px}body{font-size:15px}table{min-width:540px}th,td{padding:9px}.chips{gap:6px}.chips span{font-size:11px;padding:7px 9px}}
@media print{@page{size:A4;margin:18mm 16mm}html{scroll-behavior:auto}body{background:#fff;font:10.5pt/1.45 Georgia,serif;color:#111}nav,.topbar,.complete{display:none!important}main{margin:0;padding:0;max-width:none}.cover,.chapter{box-shadow:none;border:0;border-radius:0;max-width:none;margin:0;padding:0;background:#fff}.cover{break-after:page}.chapter{break-before:page}h1{font:34pt/1.12 Georgia,serif;color:#000}h2{font:22pt/1.25 Georgia,serif;color:#000;margin:0 0 18pt}h3{font:14pt/1.3 Georgia,serif;color:#000;break-after:avoid}p{orphans:3;widows:3;margin-bottom:10pt}h2,h3{break-after:avoid}table{font-size:9pt;min-width:0}thead{display:table-header-group}tr{break-inside:avoid}th{background:#e5ebee!important;color:#000}th,td{padding:6pt;border-color:#aaa}.table-scroll{overflow:visible}.qa{break-inside:avoid}details.qa{border:0;border-top:1px solid #ccc;border-radius:0;padding-top:8pt}details.qa summary{font-size:11pt;background:none!important;border:0!important;padding:0 0 6pt;color:#000}details.qa p{font-size:10.5pt;margin:0 0 11pt}pre{background:#f0f2f3!important;color:#111;font-size:8.5pt;white-space:pre-wrap;overflow:visible;padding:10pt;break-inside:avoid}pre code{white-space:pre-wrap;font-size:8.5pt}code{font-size:9pt}a{color:#111;text-decoration:none}.chips span{background:#eee!important;color:#000}.footer{font-size:8pt}*{-webkit-print-color-adjust:exact;print-color-adjust:exact}}
'''
js=r'''
const links=[...document.querySelectorAll('[data-chapter-link]')];
const chapters=[...document.querySelectorAll('.chapter')];
const search=document.getElementById('search');
const answers=[...document.querySelectorAll('details.qa')];
let saved={};try{saved=JSON.parse(localStorage.getItem('nexus-handbook-progress-v1')||'{}')}catch(e){}
function updateProgress(){const n=Object.values(saved).filter(Boolean).length;document.getElementById('progress').value=n;document.getElementById('progress-text').textContent=n+' of '+chapters.length+' chapters practiced';links.forEach(a=>a.classList.toggle('done',!!saved[a.dataset.chapterLink]));try{localStorage.setItem('nexus-handbook-progress-v1',JSON.stringify(saved))}catch(e){}}
document.querySelectorAll('[data-chapter]').forEach(c=>{c.checked=!!saved[c.dataset.chapter];c.addEventListener('change',()=>{saved[c.dataset.chapter]=c.checked;updateProgress()})});updateProgress();
const searchText=chapters.map(s=>s.textContent.toLowerCase());
search.addEventListener('input',()=>{const query=search.value.trim().toLowerCase();let n=0;links.forEach((a,i)=>{const show=!query||searchText[i].includes(query);a.hidden=!show;if(show)n++});document.getElementById('search-count').textContent=query?n+' matching chapters':'32 chapters · search their full text'});
document.getElementById('answers').addEventListener('click',function(){const open=answers.some(a=>!a.open);answers.forEach(a=>a.open=open);this.textContent=open?'Hide all answers':'Show all 60 answers'});
document.getElementById('reading').addEventListener('click',function(){document.body.classList.toggle('study');this.setAttribute('aria-pressed',document.body.classList.contains('study'));});
document.getElementById('menu').addEventListener('click',()=>document.body.classList.toggle('menu-open'));
document.getElementById('close-menu').addEventListener('click',()=>document.body.classList.remove('menu-open'));
links.forEach(a=>a.addEventListener('click',()=>document.body.classList.remove('menu-open')));
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.body.classList.remove('menu-open')});
let printState=[];function beforePrint(){printState=answers.map(a=>a.open);answers.forEach(a=>a.open=true)}function afterPrint(){answers.forEach((a,i)=>a.open=printState[i]??false)}window.addEventListener('beforeprint',beforePrint);window.addEventListener('afterprint',afterPrint);document.getElementById('print').addEventListener('click',()=>window.print());
const observer=new IntersectionObserver(entries=>{const visible=entries.filter(e=>e.isIntersecting);if(visible.length){const id=visible[0].target.querySelector('h2').id;links.forEach(a=>a.classList.toggle('active',a.dataset.chapterLink===id))}},{rootMargin:'-15% 0px -65% 0px'});chapters.forEach(s=>observer.observe(s));
'''
out=ROOT/'docs/NEXUS_Interview_Handbook.html'
doc=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="A self-contained NEXUS project interview handbook with architecture, models, reliable messaging, 60 interview answers and practical exercises."><title>NEXUS Project Interview Handbook</title><style>{css}</style></head><body>
<nav aria-label="Handbook chapters"><button id="close-menu" class="mobile-close" aria-label="Close contents">Close</button><div class="brand">NEXUS</div><p class="caption">PROJECT INTERVIEW HANDBOOK<br>Understand · explain · demonstrate</p><label for="search">Find a topic</label><input id="search" type="search" placeholder="Try leakage, Kafka, approval…"><div id="search-count" aria-live="polite">32 chapters · search their full text</div><div class="links">{''.join(navigation)}</div><div class="progress"><div id="progress-text"></div><progress id="progress" max="32" value="0" aria-label="Chapters practiced"></progress><div>Progress stays in this browser when local storage is available.</div></div></nav>
<header class="topbar"><button id="menu" class="mobile-menu" aria-label="Open contents">Contents</button><span class="label">Offline study edition · 14 October 2026</span><button id="reading" aria-pressed="false">Larger reading text</button><button id="answers">Show all 60 answers</button><button id="print">Print or save PDF</button></header>
<main><div class="cover"><div class="eyebrow">From first explanation to technical deep dive</div><h1>NEXUS Project<br>Interview Handbook</h1><p class="intro">Learn the business problem, understand the implementation, defend the design decisions and demonstrate the complete supply-chain simulation.</p><div class="chips"><span>32 chapters</span><span>60 interview answers</span><span>9 worked exercises</span><span>7 day study plan</span></div><p class="cover-note">One offline file. No sign-in, internet connection or external libraries required to read it. Start with the simple explanation, then follow the workflow through the models, event system, optimizer and approval controls.</p><p class="meta">Reviewed against NEXUS 4.0 source and saved verification artifacts<br>Prepared 14 October 2026 · Approximately {len(raw.split()):,} words<br>Scope: local supply-chain intelligence and simulation, not a live commercial ERP.</p></div>
{''.join(sections)}<footer class="footer">NEXUS interview study edition · Explain what the code does, support what you claim, and practice what you demonstrate.</footer></main><script>{js}</script></body></html>'''
out.write_text(doc,encoding='utf-8')
assert len(sections)==32 and doc.count('<details class="qa"')==60
assert 'src="http' not in doc and '<link ' not in doc
print(json.dumps({'output':str(out),'chapters':len(sections),'questions':60,'words':len(raw.split()),'bytes':out.stat().st_size,'sha256':hashlib.sha256(out.read_bytes()).hexdigest()},indent=2))
